package dev.celerbi.easyfarmersdelightcompat.integration.emi;
import dev.celerbi.easyfarmersdelightcompat.EasyFarmersDelightCompat;import dev.celerbi.easyfarmersdelightcompat.integration.RecipeViewerData;import dev.celerbi.easyfarmersdelightcompat.registry.ModBlocks;import dev.emi.emi.api.EmiEntrypoint;import dev.emi.emi.api.EmiPlugin;import dev.emi.emi.api.EmiRegistry;import dev.emi.emi.api.recipe.EmiRecipeCategory;import dev.emi.emi.api.stack.EmiStack;import net.minecraft.resources.ResourceLocation;
@EmiEntrypoint public final class EasyFdEmiPlugin implements EmiPlugin{
 public static final EmiRecipeCategory FARMER_HARVEST=new EmiRecipeCategory(ResourceLocation.fromNamespaceAndPath(EasyFarmersDelightCompat.MOD_ID,"farmer_harvest"),EmiStack.of(ModBlocks.RICH_FARMER_ITEM.get()));public static final EmiRecipeCategory CUTTER_AXE=new EmiRecipeCategory(ResourceLocation.fromNamespaceAndPath(EasyFarmersDelightCompat.MOD_ID,"cutter_axe"),EmiStack.of(ModBlocks.CUTTER_ITEM.get()));
 public void register(EmiRegistry r){r.addCategory(FARMER_HARVEST);r.addCategory(CUTTER_AXE);r.addWorkstation(FARMER_HARVEST,EmiStack.of(ModBlocks.RICH_FARMER_ITEM.get()));r.addWorkstation(FARMER_HARVEST,EmiStack.of(ModBlocks.RICH_PADDY_FARMER_ITEM.get()));r.addWorkstation(CUTTER_AXE,EmiStack.of(ModBlocks.CUTTER_ITEM.get()));registerCutting(r);for(var i:RecipeViewerData.FARMER_HARVESTS)r.addRecipe(new FarmerHarvestEmiRecipe(i));for(var i:RecipeViewerData.cutterAxeActions())r.addRecipe(new CutterAxeEmiRecipe(i));}
 private static void registerCutting(EmiRegistry r){Class<?> c=load("vectorwing.farmersdelight.integration.emi.FDRecipeCategories");if(c==null)return;try{var f=c.getDeclaredField("CUTTING");f.trySetAccessible();Object v=f.get(null);if(v instanceof EmiRecipeCategory cat)r.addWorkstation(cat,EmiStack.of(ModBlocks.CUTTER_ITEM.get()));}catch(ReflectiveOperationException|LinkageError ignored){}}
 private static Class<?> load(String n){ClassLoader c=Thread.currentThread().getContextClassLoader();if(c!=null)try{return Class.forName(n,true,c);}catch(ClassNotFoundException|LinkageError ignored){}try{return Class.forName(n);}catch(ClassNotFoundException|LinkageError ignored){return null;}}
}
